int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    // Parallel max finding simulation: reduce in log(n) steps
    int step = 1;
    while (step < n) {
        for (int i = 0; i + step < n; i += 2 * step) {
            a[i] = max(a[i], a[i + step]);
        }
        step *= 2;
    }
    cout << a[0] << endl;
}

