    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    // Parallel reduction simulation: iteratively reduce the array size by comparing pairs
    while (a.size() > 1) {
        vector<int> next;
        int sz = a.size();
        for (int i = 0; i + 1 < sz; i += 2) {
            next.push_back(max(a[i], a[i+1]));
        }
        if (sz % 2 == 1) next.push_back(a.back());
        a = move(next);
    }
    cout << a[0] << endl;
}

