int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int l = 0, r = n - 1;
    bool found = false;
    while (l < r) {
        long long sum = a[l] + a[r];
        if (sum == target) {
            found = true;
            break;
        } else if (sum < target) {
            ++l;
        } else {
            --r;
        }
    }

    cout << (found ? "YES" : "NO") << endl;
    return 0;
}

