#include <iostream>
#include <vector>
using namespace std;

struct FenwickTree {
    vector<long long> bit;
    int n;
    FenwickTree(int size) : n(size), bit(size + 1, 0) {}
    void add(int idx, long long val) {
        for (++idx; idx <= n; idx += idx & -idx)
            bit[idx] += val;
    }
    long long sum(int idx) {
        long long res = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
            res += bit[idx];
        return res;
    }
    long long range_sum(int l, int r) {
        return sum(r) - sum(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    FenwickTree ft(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        ft.add(i, a[i]);
    }
    for (int i = 0; i < q; ++i) {
        int l, r;
        cin >> l >> r;
        // assuming 1-based input for queries
        cout << ft.range_sum(l - 1, r - 1) << endl;
    }
}

