#include <iostream>
#include <vector>
#include <string>
using namespace std;

class BinaryHeap {
    vector<int> heap;
public:
    void insert(int x) {
        heap.push_back(x);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] < heap[i]) {
                swap(heap[p], heap[i]);
                i = p;
            } else break;
        }
    }
    int extract_max() {
        int n = heap.size();
        int res = heap[0];
        heap[0] = heap[n - 1];
        heap.pop_back();
        int i = 0;
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, largest = i;
            if (l < heap.size() && heap[l] > heap[largest]) largest = l;
            if (r < heap.size() && heap[r] > heap[largest]) largest = r;
            if (largest != i) {
                swap(heap[i], heap[largest]);
                i = largest;
            } else break;
        }
        return res;
    }
    bool empty() {
        return heap.empty();
    }
};

