}

#include <iostream>
#include <vector>
#include <cstdio>
#include <cstring>
#include <cassert>
using namespace std;

// Fibonacci Heap Node
struct Node {
    int key;
    int degree;
    bool mark;
    Node *parent, *child, *left, *right;
    Node(int k) : key(k), degree(0), mark(false), parent(nullptr), child(nullptr), left(this), right(this) {}
};

class FibonacciHeap {
    Node* maxNode;
    int nNodes;
public:
    FibonacciHeap() : maxNode(nullptr), nNodes(0) {}

    void insert(int key) {
        Node* node = new Node(key);
        if (!maxNode) {
            maxNode = node;
        } else {
            // Insert node into root list
            node->left = maxNode;
            node->right = maxNode->right;
            maxNode->right->left = node;
            maxNode->right = node;
            if (node->key > maxNode->key) maxNode = node;
        }
        nNodes++;
    }

    int extractMax() {
        Node* z = maxNode;
        if (z) {
            // Add children to root list
            if (z->child) {
                Node* c = z->child;
                do {
                    Node* next = c->right;
                    // Remove c from child list
                    c->left->right = c->right;
                    c->right->left = c->left;
                    // Add c to root list
                    c->left = maxNode;
                    c->right = maxNode->right;
                    maxNode->right->left = c;
                    maxNode->right = c;
                    c->parent = nullptr;
                    c = next;
                } while (c != z->child);
            }
            // Remove z from root list
            z->left->right = z->right;
            z->right->left = z->left;
            if (z == z->right) {
                maxNode = nullptr;
            } else {
                maxNode = z->right;
                consolidate();
            }
            nNodes--;
            int ret = z->key;
            delete z;
            return ret;
        }
        return -1; // Should not happen
    }

private:
    void consolidate() {
        int D = 50; // log2(1e5) < 20, but for safety
        vector<Node*> A(D, nullptr);
        vector<Node*> rootList;
        Node* w = maxNode;
        if (!w) return;
        do {
            rootList.push_back(w);
            w = w->right;
        } while (w != maxNode);
        for (Node* w : rootList) {
            Node* x = w;
            int d = x->degree;
            while (A[d]) {
                Node* y = A[d];
                if (x->key < y->key) swap(x, y);
                link(y, x);
                A[d] = nullptr;
                d++;
            }
            A[d] = x;
        }
        maxNode = nullptr;
        for (Node* y : A) {
            if (y) {
                if (!maxNode) {
                    y->left = y->right = y;
                    maxNode = y;
                } else {
                    // Insert y into root list
                    y->left = maxNode;
                    y->right = maxNode->right;
                    maxNode->right->left = y;
                    maxNode->right = y;
                    if (y->key > maxNode->key) maxNode = y;
                }
            }
        }
    }

    void link(Node* y, Node* x) {
        // Remove y from root list
        y->left->right = y->right;
        y->right->left = y->left;
        // Make y a child of x
        y->parent = x;
        if (!x->child) {
            y->left = y->right = y;
            x->child = y;
        } else {
            y->left = x->child;
            y->right = x->child->right;
            x->child->right->left = y;
            x->child->right = y;
        }
        x->degree++;
        y->mark = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    FibonacciHeap heap;
    while (q--) {
        string op;
        cin >> op;
        if (op == "insert") {
            int x;
            cin >> x;
            heap.insert(x);
        } else if (op == "extract-max") {
            int res = heap.extractMax();
            cout << res << endl;
        }
    }
    return 0;
}

