const int INF = 1e9+7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n+1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int s, t;
    cin >> s >> t;

    if (s == t) {
        cout << 0 << endl;
        return 0;
    }

    vector<int> dist_s(n+1, INF), dist_t(n+1, INF);
    vector<bool> vis_s(n+1, false), vis_t(n+1, false);
    queue<int> qs, qt;

    dist_s[s] = 0; vis_s[s] = true; qs.push(s);
    dist_t[t] = 0; vis_t[t] = true; qt.push(t);

    int answer = INF;

    while (!qs.empty() || !qt.empty()) {
        // Expand from source side
        if (!qs.empty()) {
            int sz = qs.size();
            while (sz--) {
                int u = qs.front(); qs.pop();
                for (int v : adj[u]) {
                    if (!vis_s[v]) {
                        dist_s[v] = dist_s[u] + 1;
                        vis_s[v] = true;
                        qs.push(v);
                        if (vis_t[v]) {
                            answer = min(answer, dist_s[v] + dist_t[v]);
                        }
                    }
                }
            }
        }
        // Expand from target side
        if (!qt.empty()) {
            int sz = qt.size();
            while (sz--) {
                int u = qt.front(); qt.pop();
                for (int v : adj[u]) {
                    if (!vis_t[v]) {
                        dist_t[v] = dist_t[u] + 1;
                        vis_t[v] = true;
                        qt.push(v);
                        if (vis_s[v]) {
                            answer = min(answer, dist_s[v] + dist_t[v]);
                        }
                    }
                }
            }
        }
        if (answer != INF) break;
    }

    if (answer == INF) cout << -1 << endl;
    else cout << answer << endl;

    return 0;
}

