typedef long long ll;
typedef pair<ll, int> pli;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, ll>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        ll w;
        cin >> u >> v >> w;
        adj[u].emplace_back(v, w);
        // If the graph is undirected, uncomment the next line:
        // adj[v].emplace_back(u, w);
    }
    int src, dest;
    cin >> src >> dest;

    vector<ll> dist(n + 1, numeric_limits<ll>::max());
    vector<bool> visited(n + 1, false);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[src] = 0;
    pq.emplace(0, src);

    while (!pq.empty()) {
        ll d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (visited[u]) continue;
        visited[u] = true;
        for (auto &edge : adj[u]) {
            int v = edge.first;
            ll w = edge.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.emplace(dist[v], v);
            }
        }
    }

    if (dist[dest] == numeric_limits<ll>::max()) {
        cout << "-1\n";
    } else {
        cout << dist[dest] << endl;
    }
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

struct Edge {
    int to;
    ll weight;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<Edge>> adj(n), radj(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        ll w;
        cin >> u >> v >> w;
        --u; --v;
        adj[u].push_back({v, w});
        radj[v].push_back({u, w});
    }
    int s, t;
    cin >> s >> t;
    --s; --t;

    vector<ll> dist_f(n, INF), dist_b(n, INF);
    vector<bool> vis_f(n, false), vis_b(n, false);

    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq_f, pq_b;

    dist_f[s] = 0;
    dist_b[t] = 0;
    pq_f.push({0, s});
    pq_b.push({0, t});

    ll ans = INF;

    while (!pq_f.empty() || !pq_b.empty()) {
        // Forward step
        if (!pq_f.empty()) {
            auto [d, u] = pq_f.top(); pq_f.pop();
            if (vis_f[u]) continue;
            vis_f[u] = true;
            if (vis_b[u]) ans = min(ans, dist_f[u] + dist_b[u]);
            for (auto &e : adj[u]) {
                if (dist_f[e.to] > dist_f[u] + e.weight) {
                    dist_f[e.to] = dist_f[u] + e.weight;
                    pq_f.push({dist_f[e.to], e.to});
                }
            }
        }
        // Backward step
        if (!pq_b.empty()) {
            auto [d, u] = pq_b.top(); pq_b.pop();
            if (vis_b[u]) continue;
            vis_b[u] = true;
            if (vis_f[u]) ans = min(ans, dist_f[u] + dist_b[u]);
            for (auto &e : radj[u]) {
                if (dist_b[e.to] > dist_b[u] + e.weight) {
                    dist_b[e.to] = dist_b[u] + e.weight;
                    pq_b.push({dist_b[e.to], e.to});
                }
            }
        }
    }

    for (int u = 0; u < n; ++u) {
        if (dist_f[u] < INF && dist_b[u] < INF) {
            ans = min(ans, dist_f[u] + dist_b[u]);
        }
    }

    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

