#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int INF = 1e9+7;

struct SegmentTree {
    int n;
    vector<int> tree;
    SegmentTree(int size) {
        n = 1;
        while (n < size) n <<= 1;
        tree.assign(2 * n, INF);
    }
    void build(const vector<int>& a) {
        for (int i = 0; i < (int)a.size(); ++i) tree[n + i] = a[i];
        for (int i = n - 1; i > 0; --i)
            tree[i] = min(tree[2 * i], tree[2 * i + 1]);
    }
    void update(int pos, int value) {
        pos += n;
        tree[pos] = value;
        for (pos /= 2; pos > 0; pos /= 2)
            tree[pos] = min(tree[2 * pos], tree[2 * pos + 1]);
    }
    int query(int l, int r) { // [l, r)
        int res = INF;
        l += n; r += n;
        while (l < r) {
            if (l & 1) res = min(res, tree[l++]);
            if (r & 1) res = min(res, tree[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SegmentTree st(n);
    st.build(a);
    for (int i = 0; i < q; ++i) {
        int type;
        cin >> type;
        if (type == 1) {
            int pos, value;
            cin >> pos >> value;
            --pos;
            st.update(pos, value);
        } else if (type == 2) {
            int l, r;
            cin >> l >> r;
            --l;
            cout << st.query(l, r) << endl;
        }
    }
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int INF = 1e9+7;

struct SegmentTree {
    int n;
    vector<int> tree, lazy;

    SegmentTree(int size) {
        n = size;
        tree.assign(4*n, INF);
        lazy.assign(4*n, 0);
    }

    void push(int v, int tl, int tr) {
        if (lazy[v] != 0) {
            tree[v] += lazy[v];
            if (tl != tr) {
                lazy[2*v] += lazy[v];
                lazy[2*v+1] += lazy[v];
            }
            lazy[v] = 0;
        }
    }

    void build(const vector<int>& a, int v, int tl, int tr) {
        if (tl == tr) {
            tree[v] = a[tl];
        } else {
            int tm = (tl + tr) / 2;
            build(a, v*2, tl, tm);
            build(a, v*2+1, tm+1, tr);
            tree[v] = min(tree[v*2], tree[v*2+1]);
        }
    }

    void point_update(int v, int tl, int tr, int pos, int new_val) {
        push(v, tl, tr);
        if (tl == tr) {
            tree[v] = new_val;
        } else {
            int tm = (tl + tr) / 2;
            if (pos <= tm)
                point_update(v*2, tl, tm, pos, new_val);
            else
                point_update(v*2+1, tm+1, tr, pos, new_val);
            tree[v] = min(tree[v*2], tree[v*2+1]);
        }
    }

    int range_min(int v, int tl, int tr, int l, int r) {
        push(v, tl, tr);
        if (l > r) return INF;
        if (l == tl && r == tr) {
            return tree[v];
        }
        int tm = (tl + tr) / 2;
        return min(
            range_min(v*2, tl, tm, l, min(r, tm)),
            range_min(v*2+1, tm+1, tr, max(l, tm+1), r)
        );
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    SegmentTree st(n);
    st.build(a, 1, 0, n-1);

    for (int i = 0; i < q; ++i) {
        int type;
        cin >> type;
        if (type == 1) {
            int pos, val;
            cin >> pos >> val;
            --pos;
            st.point_update(1, 0, n-1, pos, val);
        } else if (type == 2) {
            int l, r;
            cin >> l >> r;
            --l; --r;
            cout << st.range_min(1, 0, n-1, l, r) << endl;
        }
    }
}

