        if (type == 1) {
            // point update: set a[p] = x
            int p, x;
            cin >> p >> x;
            --p;
            a[p] = x;
            int b = p / B;
            block_min[b] = INT_MAX;
            int l = b * B, r = min(n, (b + 1) * B);
            for (int i = l; i < r; ++i) {
                block_min[b] = min(block_min[b], a[i]);
            }
        } else if (type == 2) {
            // range min query: [l, r)
            int l, r;
            cin >> l >> r;
            --l;
            int ans = INT_MAX;
            int start_block = l / B, end_block = (r - 1) / B;
            if (start_block == end_block) {
                for (int i = l; i < r; ++i) ans = min(ans, a[i]);
            } else {
                int end_l = (start_block + 1) * B;
                for (int i = l; i < end_l; ++i) ans = min(ans, a[i]);
                for (int b = start_block + 1; b < end_block; ++b) ans = min(ans, block_min[b]);
                int start_r = end_block * B;
                for (int i = start_r; i < r; ++i) ans = min(ans, a[i]);
            }
            cout << ans << endl;
        }
    }
}

