    vector<long long> a(n);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total += a[i];
    }

    // Find maximum subarray sum (Kadane's algorithm)
    long long max_sum = a[0], curr = a[0];
    for (int i = 1; i < n; ++i) {
        curr = max(a[i], curr + a[i]);
        max_sum = max(max_sum, curr);
    }

    // Check if there exists a subarray with sum > total - sum
    // i.e., sum > total - sum => 2*sum > total => sum > total/2
    if (max_sum > total / 2.0) {
