using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total += a[i];
    }

    // We want to find if there exists a subarray with sum > total - sum
    // That is, sum > total/2

    long long target = total / 2;
    // If total is odd, sum > target (since target is floor(total/2))

    // Use prefix sums and binary search for subarrays
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + a[i];
    }

    bool found = false;
    // For each possible starting point, binary search for the minimal end point
    // such that subarray sum > target
    for (int i = 0; i < n; ++i) {
        int lo = i + 1, hi = n, pos = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            long long sub_sum = prefix[mid] - prefix[i];
            if (sub_sum > target) {
                pos = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        if (pos != -1) {
            found = true;
            break;
        }
    }

    cout << (found ? "YES" : "NO") << endl;
}

