#include <iostream>
#include <cmath>
using namespace std;

typedef long long ll;

ll gcd(ll a, ll b) {
    while (b) {
        ll t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ll x;
    cin >> x;
    ll a = 1, b = x;
    ll min_diff = x - 1;
    for (ll i = 1; i * i <= x; ++i) {
        if (x % i == 0) {
            ll j = x / i;
            if (gcd(i, j) == 1) {
                ll diff = abs(i - j);
                if (diff < min_diff) {
                    min_diff = diff;
                    a = i;
                    b = j;
                }
            }
        }
    }
    cout << a << " " << b << endl;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct TrieNode {
    TrieNode* child[2];
    TrieNode() {
        child[0] = child[1] = nullptr;
    }
};

class Trie {
public:
    TrieNode* root;
    Trie() {
        root = new TrieNode();
    }
    void insert(int num) {
        TrieNode* node = root;
        for (int i = 30; i >= 0; --i) {
            int b = (num >> i) & 1;
            if (!node->child[b]) node->child[b] = new TrieNode();
            node = node->child[b];
        }
    }
    int maxXor(int num) {
        TrieNode* node = root;
        int res = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (num >> i) & 1;
            if (node->child[1-b]) {
                res |= (1 << i);
                node = node->child[1-b];
            } else {
                node = node->child[b];
            }
        }
        return res;
    }
    void clear(TrieNode* node) {
        if (!node) return;
        clear(node->child[0]);
        clear(node->child[1]);
        delete node;
    }
    ~Trie() {
        clear(root);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    // Step 1: Compute original max XOR
    Trie trie;
    int orig_max = 0;
    for (int i = 0; i < n; ++i) trie.insert(a[i]);
    for (int i = 0; i < n; ++i) {
        orig_max = max(orig_max, trie.maxXor(a[i]));
    }

    int ans = orig_max;

    // Step 2: Try changing each element to any other value in the array
    // For each a[i], try replacing it with a[j] (j != i)
    for (int i = 0; i < n; ++i) {
        // Remove a[i] from trie
        Trie tempTrie;
        for (int k = 0; k < n; ++k) {
            if (k != i) tempTrie.insert(a[k]);
        }
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            int max_xor = 0;
            for (int k = 0; k < n; ++k) {
                if (k == i) {
                    max_xor = max(max_xor, tempTrie.maxXor(a[j]));
                } else {
                    max_xor = max(max_xor, tempTrie.maxXor(a[k]));
                }
            }
            ans = min(ans, max_xor);
        }
    }

    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct TrieNode {
    TrieNode* child[2];
    TrieNode() {
        child[0] = child[1] = nullptr;
    }
};

class Trie {
public:
    TrieNode* root;
    Trie() {
        root = new TrieNode();
    }
    void insert(int num) {
        TrieNode* node = root;
        for (int i = 30; i >= 0; --i) {
            int b = (num >> i) & 1;
            if (!node->child[b]) node->child[b] = new TrieNode();
            node = node->child[b];
        }
    }
    int query(int num) {
        TrieNode* node = root;
        int res = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (num >> i) & 1;
            if (node->child[b]) {
                node = node->child[b];
            } else {
                node = node->child[b ^ 1];
                res |= (1 << i);
            }
        }
        return res;
    }
    void clear(TrieNode* node) {
        if (!node) return;
        clear(node->child[0]);
        clear(node->child[1]);
        delete node;
    }
    ~Trie() {
        clear(root);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    // Step 1: Compute initial maximum XOR
    Trie trie;
    int max_xor = 0;
    for (int i = 0; i < n; ++i) trie.insert(a[i]);
    for (int i = 0; i < n; ++i) {
        int cur = trie.query(a[i]);
        if (cur > max_xor) max_xor = cur;
    }

    // Step 2: Try changing each element to any other value in the array (at most one operation)
    // Since n is large, we try changing to 0 or to a value close to a[i] (e.g., a[i]^max_xor)
    // But for efficiency, try changing a[i] to a[j] for all j (brute force is too slow)
    // Instead, try changing a[i] to 0 and to a[i]^max_xor

    int answer = max_xor;
    for (int i = 0; i < n; ++i) {
        // Remove a[i] from trie
        Trie temp_trie;
        for (int j = 0; j < n; ++j) if (j != i) temp_trie.insert(a[j]);
        // Try changing a[i] to 0
        int cur_max = 0;
        for (int j = 0; j < n; ++j) if (j != i) {
            int q = temp_trie.query(a[j]);
            if (q > cur_max) cur_max = q;
        }
        int q0 = temp_trie.query(0);
        if (q0 > cur_max) cur_max = q0;
        answer = min(answer, cur_max);

        // Try changing a[i] to a[i]^max_xor
        int new_val = a[i] ^ max_xor;
        cur_max = 0;
        for (int j = 0; j < n; ++j) if (j != i) {
            int q = temp_trie.query(a[j]);
            if (q > cur_max) cur_max = q;
        }
        int q1 = temp_trie.query(new_val);
        if (q1 > cur_max) cur_max = q1;
        answer = min(answer, cur_max);
    }

    cout << answer << endl;
}

#include <iostream>
