using namespace std;

struct Event {
    int x, type, idx;
    // type: 1 = start, -1 = end
    bool operator<(const Event& other) const {
        if (x != other.x) return x < other.x;
        return type > other.type; // start before end at same x
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<pair<int, int>> seg(n);
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        int l, r;
        cin >> l >> r;
        seg[i] = {l, r};
        events.push_back({l, 1, i});
        events.push_back({r, -1, i});
    }
    sort(events.begin(), events.end());

    vector<int> cnt(n, 0); // cnt[i]: how many times seg i is the unique topmost
    int active = 0;
    int last_x = 0;
    int unique_idx = -1;
    for (size_t i = 0; i < events.size(); ++i) {
        int x = events[i].x;
        if (i > 0 && x > last_x && active == 1 && unique_idx != -1) {
            cnt[unique_idx] += x - last_x;
        }
        if (events[i].type == 1) {
            ++active;
            unique_idx = events[i].idx;
        } else {
            --active;
            if (active == 1) {
                // find the only active segment
                // scan forward to next start or end
                for (size_t j = i + 1; j < events.size(); ++j) {
                    if (events[j].x != x) break;
                    if (events[j].type == 1) {
                        unique_idx = events[j].idx;
                        break;
                    }
                }
            } else {
                unique_idx = -1;
            }
        }
        last_x = x;
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (cnt[i] > 0) ++ans;
    }
    cout << ans << endl;
}

