struct Segment {
    int l, r, idx;
};

struct Event {
    int x, type, idx;
    bool operator<(const Event& o) const {
        if (x != o.x) return x < o.x;
        return type > o.type; // start (+1) before end (-1)
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Segment> segs(n);
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        int l, r;
        cin >> l >> r;
        segs[i] = {l, r, i};
        events.push_back({l, 1, i});
        events.push_back({r, -1, i});
    }
    sort(events.begin(), events.end());

    vector<int> topmost_count(n, 0);
    set<int> active;
    int prev_x = events[0].x;
    for (size_t i = 0; i < events.size(); ++i) {
        int x = events[i].x;
        if (!active.empty() && x > prev_x) {
            // The topmost is the segment with the largest idx (last inserted)
            int top = *active.rbegin();
            topmost_count[top] += x - prev_x;
        }
        if (events[i].type == 1) {
            active.insert(events[i].idx);
        } else {
            active.erase(events[i].idx);
        }
        prev_x = x;
    }

    // Now, for each segment, check if after removing it, the set of topmost segments changes
    // A segment is "topmost" if it covers at least one point where it is the last inserted (top)
    int result = 0;
    for (int i = 0; i < n; ++i) {
        if (topmost_count[i] > 0) result++;
    }
    cout << result << endl;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
using namespace std;

struct Segment {
    int l, r, idx;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<Segment> segs(n);
    vector<pair<int, int>> events; // {pos, type: +idx for start, -idx for end}
    for (int i = 0; i < n; ++i) {
        cin >> segs[i].l >> segs[i].r;
        segs[i].idx = i;
        events.emplace_back(segs[i].l, i + 1); // start event
        events.emplace_back(segs[i].r + 1, -(i + 1)); // end event
    }
    sort(events.begin(), events.end());

    vector<int> topmost_count(n, 0); // how many times each segment is topmost
    set<int> active; // indices of active segments
    int prev = events[0].first;
    int top = -1;
    for (size_t i = 0; i < events.size(); ++i) {
        int pos = events[i].first;
        // For all positions between prev and pos-1, the topmost is the last inserted
        if (top != -1 && pos > prev) {
            topmost_count[top] += pos - prev;
        }
        // Process all events at this position
        while (i < events.size() && events[i].first == pos) {
            int idx = abs(events[i].second) - 1;
            if (events[i].second > 0) {
                active.insert(idx);
            } else {
                active.erase(idx);
            }
            ++i;
        }
        --i;
        // Update top
        if (!active.empty()) {
            top = *active.rbegin();
        } else {
            top = -1;
        }
        prev = pos;
    }

    // Now, for each segment, check if after removing it, it ever becomes topmost
    // A segment is "topmost after removing one" if it was ever topmost before
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (topmost_count[i] > 0) ++ans;
    }
    cout << ans << endl;
}

#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> pos(k), val(k);
    vector<bool> is_fixed(n, false);
    vector<int> fixed_val(n, -1);

    for (int i = 0; i < k; ++i) {
        cin >> pos[i];
    }
    for (int i = 0; i < k; ++i) {
        cin >> val[i];
    }
    for (int i = 0; i < k; ++i) {
        --pos[i];
        is_fixed[pos[i]] = true;
        fixed_val[pos[i]] = val[i];
    }

    set<int> unused;
    for (int i = 1; i <= n; ++i) unused.insert(i);
    for (int i = 0; i < n; ++i) {
        if (is_fixed[i]) unused.erase(fixed_val[i]);
    }

    vector<int> res(n, -1);
    for (int i = 0; i < n; ++i) {
        if (is_fixed[i]) res[i] = fixed_val[i];
    }

    // Fill unfixed positions greedily
    for (int i = 0; i < n; ++i) {
        if (!is_fixed[i]) {
            int left = -1, right = -1;
            for (int l = i - 1; l >= 0; --l) {
                if (res[l] != -1) {
                    left = res[l];
                    break;
                }
            }
            for (int r = i + 1; r < n; ++r) {
                if (res[r] != -1) {
                    right = res[r];
                    break;
                }
            }
            int target;
            if (left != -1 && right != -1) {
                target = (left + right) / 2;
            } else if (left != -1) {
                target = left;
            } else if (right != -1) {
                target = right;
            } else {
                target = (n + 1) / 2;
            }
            // Find closest unused number to target
            auto it = unused.lower_bound(target);
            int pick;
            if (it == unused.end()) {
                pick = *prev(it);
            } else if (it == unused.begin()) {
                pick = *it;
            } else {
                int a = *it;
                int b = *prev(it);
                if (abs(a - target) < abs(b - target)) pick = a;
                else pick = b;
            }
            res[i] = pick;
            unused.erase(pick);
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << res[i] << " \n"[i == n - 1];
    }
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// For each node, store its children
vector<vector<int>> tree;
vector<int> inorder;
int n, idx = 0;
bool possible = true;

// DFS to simulate in-order traversal and check matching
void dfs(int u, int parent) {
    int children = 0;
    int left = -1, right = -1;
    for (int v : tree[u]) {
        if (v != parent) {
            if (children == 0) left = v;
            else right = v;
            ++children;
        }
    }
    if (left != -1) dfs(left, u);
    // Visit current node: check if we have enough inorder elements
    if (idx >= n) {
        possible = false;
        return;
    }
    // We don't care about actual values, just structure
    ++idx;
    if (right != -1) dfs(right, u);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    tree.assign(n, vector<int>());
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    inorder.resize(n);
    for (int i = 0; i < n; ++i) cin >> inorder[i];

    // Check if the tree is a binary tree (each node has at most 2 children)
    for (int i = 0; i < n; ++i) {
        if (tree[i].size() > 3) { // parent + 2 children
            cout << "NO\n";
            return 0;
        }
    }

    // Find a root (any node)
    dfs(0, -1);

    if (possible && idx == n) cout << "YES\n";
    else cout << "NO\n";
}

