#include <vector>
#include <queue>
using namespace std;

// Function to check if the given in-order sequence can be assigned to the tree
bool inorder_traversal_matching(int n, const vector<vector<int>>& tree, const vector<int>& inorder) {
    vector<int> left(n, -1), right(n, -1), parent(n, -1);
    // Build left/right child arrays and parent array
    for (int u = 0; u < n; ++u) {
        for (int v : tree[u]) {
            if (left[u] == -1) left[u] = v;
            else right[u] = v;
            parent[v] = u;
        }
    }
    // Find root
    int root = 0;
    while (parent[root] != -1) root = parent[root];

    // Simulate in-order traversal and check structure
    int idx = 0;
    bool ok = true;
    function<void(int)> dfs = [&](int u) {
        if (u == -1) return;
        dfs(left[u]);
        if (idx >= n) { ok = false; return; }
        // No need to check value, just structure
        ++idx;
        dfs(right[u]);
    };
    dfs(root);
    if (idx != n) ok = false;
    return ok;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> tree(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    vector<int> inorder(n);
    for (int i = 0; i < n; ++i) {
        cin >> inorder[i];
    }

    // Build a rooted binary tree from the undirected tree
    // If any node has degree > 3, impossible
    bool possible = true;
    for (int i = 0; i < n; ++i) {
        if (tree[i].size() > 3) {
            possible = false;
            break;
        }
    }
    if (!possible) {
        cout << "NO\n";
        return 0;
    }

    // Root the tree at any node (say, 0)
    vector<vector<int>> bin_tree(n);
    vector<bool> vis(n, false);
    queue<int> q;
    q.push(0);
    vis[0] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : tree[u]) {
            if (!vis[v]) {
                bin_tree[u].push_back(v);
                vis[v] = true;
                q.push(v);
            }
        }
    }

    if (inorder_traversal_matching(n, bin_tree, inorder)) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }
}

#include <iostream>
#include <vector>
#include <functional>
using namespace std;

// Interactive comparison: returns true if a < b in the hidden permutation
bool ask(int a, int b) {
    cout << "? " << a + 1 << " " << b + 1 << endl;
    string res;
    cin >> res;
    return res == "<";
}

// Merge sort with interactive comparisons
void merge_sort(vector<int>& arr, int l, int r, vector<int>& tmp) {
    if (r - l <= 1) return;
    int m = (l + r) / 2;
    merge_sort(arr, l, m, tmp);
    merge_sort(arr, m, r, tmp);
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (ask(arr[i], arr[j])) {
            tmp[k++] = arr[i++];
        } else {
            tmp[k++] = arr[j++];
        }
    }
    while (i < m) tmp[k++] = arr[i++];
    while (j < r) tmp[k++] = arr[j++];
    for (int x = l; x < r; ++x) arr[x] = tmp[x];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> arr(n), tmp(n);
    for (int i = 0; i < n; ++i) arr[i] = i;

    merge_sort(arr, 0, n, tmp);

    vector<int> pos(n);
    for (int i = 0; i < n; ++i) pos[arr[i]] = i + 1;

    cout << "! ";
    for (int i = 0; i < n; ++i) cout << pos[i] << " ";
    cout << endl;
    return 0;
}

