#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Interactive query: returns true if perm[i] < perm[j]
bool ask(int i, int j) {
    cout << "? " << i+1 << " " << j+1 << endl;
    string res;
    cin >> res;
    return res == "<";
}

void answer(const vector<int>& perm) {
    cout << "! ";
    for (int x : perm) cout << x << " ";
    cout << endl;
}

void merge_sort(vector<int>& idx, vector<int>& tmp, int l, int r) {
    if (r - l <= 1) return;
    int m = (l + r) / 2;
    merge_sort(idx, tmp, l, m);
    merge_sort(idx, tmp, m, r);
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (ask(idx[i], idx[j])) tmp[k++] = idx[i++];
        else tmp[k++] = idx[j++];
    }
    while (i < m) tmp[k++] = idx[i++];
    while (j < r) tmp[k++] = idx[j++];
    for (int t = l; t < r; ++t) idx[t] = tmp[t];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> idx(n), tmp(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    merge_sort(idx, tmp, 0, n);
    vector<int> perm(n);
    for (int i = 0; i < n; ++i) perm[idx[i]] = i+1;
    answer(perm);
    return 0;
}
